import type { Kind, World } from './types'
import { meanEnergy, meanTrait } from './world'

export type Sample = {
  t: number
  fruit: number
  blue: number
  red: number
  blueEnergy: number
  redEnergy: number
  blueSpeed: number
  redSpeed: number
