    this.samples = []
    this.interval = BASE
    this.nextAt = 0
    this.version++
  }

  maybeSample(world: World) {
    if (world.t + 1e-9 < this.nextAt) return
    this.nextAt = world.t + this.interval
    this.samples.push(snapshot(world))
    if (this.samples.length > MAX) {
      this.samples = this.samples.filter((_, i) => i % 2 === 0)
      this.interval *= 2
    }
    this.version++
  }
}

