function LineChart({ samples }: { samples: Sample[] }) {
  const ref = useRef<HTMLCanvasElement>(null)
  useEffect(() => {
    const canvas = ref.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    const dpr = Math.min(2, window.devicePixelRatio || 1)
    const w = canvas.clientWidth
    const h = canvas.clientHeight
    canvas.width = w * dpr
    canvas.height = h * dpr
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, w, h)
    if (samples.length < 2) return

    const pad = { l: 28, r: 10, t: 10, b: 18 }
    const innerW = w - pad.l - pad.r
    const innerH = h - pad.t - pad.b
    const t0 = samples[0]!.t
    const t1 = samples[samples.length - 1]!.t
    const span = Math.max(1, t1 - t0)
    const maxFruit = Math.max(1, ...samples.map((s) => s.fruit))
    const maxPop = Math.max(1, ...samples.map((s) => Math.max(s.blue, s.red)))

    ctx.strokeStyle = 'rgba(200, 220, 210, 0.12)'
    ctx.lineWidth = 1
    for (let i = 0; i <= 3; i++) {
      const y = pad.t + (innerH * i) / 3
      ctx.beginPath()
      ctx.moveTo(pad.l, y)
      ctx.lineTo(w - pad.r, y)
      ctx.stroke()
    }

    const xAt = (t: number) => pad.l + ((t - t0) / span) * innerW
    const yFruit = (v: number) => pad.t + innerH - (v / maxFruit) * innerH
    const yPop = (v: number) => pad.t + innerH - (v / maxPop) * innerH

    const stroke = (key: 'fruit' | 'blue' | 'red', color: string, yOf: (v: number) => number) => {
      ctx.beginPath()
      samples.forEach((s, i) => {
        const x = xAt(s.t)
        const y = yOf(s[key])
        if (i === 0) ctx.moveTo(x, y)
        else ctx.lineTo(x, y)
      })
      ctx.strokeStyle = color
      ctx.lineWidth = 1.8
      ctx.stroke()
    }
    stroke('fruit', COL.fruit, yFruit)
    stroke('blue', COL.blue, yPop)
    stroke('red', COL.red, yPop)

    ctx.fillStyle = 'rgba(210, 224, 218, 0.55)'
    ctx.font = '10px "JetBrains Mono", monospace'
    ctx.fillText(`${Math.round(t0)}s`, pad.l, h - 4)
    ctx.textAlign = 'right'
    ctx.fillText(`${Math.round(t1)}s`, w - pad.r, h - 4)
    ctx.textAlign = 'left'
    ctx.fillText(`pop ${maxPop}`, 4, pad.t + 8)
    ctx.fillStyle = COL.fruit
    ctx.fillText(`fruit ${maxFruit}`, 4, pad.t + 20)
  }, [samples, samples.length, samples.at(-1)?.t])

  return <canvas ref={ref} className="plot" />
}

function PhasePlot({ samples }: { samples: Sample[] }) {
  const ref = useRef<HTMLCanvasElement>(null)
  useEffect(() => {
    const canvas = ref.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    const dpr = Math.min(2, window.devicePixelRatio || 1)
    const w = canvas.clientWidth
    const h = canvas.clientHeight
    canvas.width = w * dpr
    canvas.height = h * dpr
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, w, h)
    const pad = 16
    const maxB = Math.max(1, ...samples.map((s) => s.blue))
    const maxR = Math.max(1, ...samples.map((s) => s.red))
    ctx.strokeStyle = 'rgba(200, 220, 210, 0.14)'
    ctx.strokeRect(pad, pad, w - pad * 2, h - pad * 2)
    if (samples.length < 2) return
    ctx.beginPath()
    samples.forEach((s, i) => {
      const x = pad + (s.blue / maxB) * (w - pad * 2)
      const y = h - pad - (s.red / maxR) * (h - pad * 2)
      if (i === 0) ctx.moveTo(x, y)
      else ctx.lineTo(x, y)
    })
    ctx.strokeStyle = 'rgba(180, 200, 210, 0.55)'
    ctx.lineWidth = 1.3
    ctx.stroke()
    const last = samples[samples.length - 1]!
    const x = pad + (last.blue / maxB) * (w - pad * 2)
    const y = h - pad - (last.red / maxR) * (h - pad * 2)
    ctx.beginPath()
    ctx.arc(x, y, 3.5, 0, Math.PI * 2)
    ctx.fillStyle = COL.red
    ctx.fill()
    ctx.fillStyle = 'rgba(210, 224, 218, 0.55)'
    ctx.font = '10px "JetBrains Mono", monospace'
    ctx.fillText('blue →', pad, h - 4)
    ctx.save()
    ctx.translate(10, h - pad)
    ctx.rotate(-Math.PI / 2)
    ctx.fillText('red', 0, 0)
    ctx.restore()
  }, [samples, samples.length, samples.at(-1)?.t])
  return <canvas ref={ref} className="plot" />
}

function TraitChart({ samples }: { samples: Sample[] }) {
  const last = samples.at(-1)
  return (
    <div className="traits">
      <p>
        blue speed <b>{(last?.blueSpeed ?? 1).toFixed(2)}</b>
        <span> vision {(last?.blueVision ?? 1).toFixed(2)}</span>
      </p>
      <p>
        red speed <b>{(last?.redSpeed ?? 1).toFixed(2)}</b>
        <span> vision {(last?.redVision ?? 1).toFixed(2)}</span>
      </p>
      <Mini samples={samples} />
    </div>
  )
}

function Mini({ samples }: { samples: Sample[] }) {
  const ref = useRef<HTMLCanvasElement>(null)
  useEffect(() => {
    const canvas = ref.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    const dpr = Math.min(2, window.devicePixelRatio || 1)
    const w = canvas.clientWidth
    const h = canvas.clientHeight
    canvas.width = w * dpr
    canvas.height = h * dpr
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, w, h)
    if (samples.length < 2) return
    const t0 = samples[0]!.t
    const span = Math.max(1, samples[samples.length - 1]!.t - t0)
    const vals = samples.flatMap((s) => [s.blueSpeed, s.redSpeed])
    const lo = Math.min(...vals) - 0.02
    const hi = Math.max(...vals) + 0.02
    const yOf = (v: number) => h - 4 - ((v - lo) / (hi - lo)) * (h - 8)
    const stroke = (key: 'blueSpeed' | 'redSpeed', color: string) => {
      ctx.beginPath()
      samples.forEach((s, i) => {
        const x = ((s.t - t0) / span) * w
        const y = yOf(s[key])
        if (i === 0) ctx.moveTo(x, y)
        else ctx.lineTo(x, y)
      })
      ctx.strokeStyle = color
      ctx.lineWidth = 1.5
      ctx.stroke()
    }
    stroke('blueSpeed', COL.blue)
    stroke('redSpeed', COL.red)
  }, [samples, samples.length, samples.at(-1)?.t])
  return <canvas ref={ref} className="plot mini" />
}

export function Inspector({ engine }: Props) {
  useSyncExternalStore(engine.subscribe, engine.getSnapshot)
  const blob = engine.selected()
  if (!blob) {
    return (
      <aside className="inspector empty">
        <p>Click a blob on the dish to see energy, age, and what it is doing.</p>
      </aside>
    )
  }
  return (
    <aside className="inspector" data-kind={blob.kind}>
      <header>
        <b>{blob.kind} blob</b>
        <span>#{blob.id}</span>
      </header>
      <dl>
        <div>
          <dt>Energy</dt>
          <dd>{blob.energy.toFixed(1)}</dd>
        </div>
        <div>
          <dt>Age</dt>
          <dd>{blob.age.toFixed(1)}s</dd>
        </div>
        <div>
          <dt>Action</dt>
          <dd>{ACTIONS[blob.action]}</dd>
        </div>
        <div>
          <dt>Speed</dt>
          <dd>
            {(blob.kind === 'blue' ? engine.params.blueSpeed : engine.params.redSpeed) * blob.traits.speed}
            <small> ×{blob.traits.speed.toFixed(2)}</small>
          </dd>
        </div>
        <div>
          <dt>Sensing</dt>
          <dd>
            {((blob.kind === 'blue' ? engine.params.blueVision : engine.params.redVision) * blob.traits.vision).toFixed(0)}
            <small> ×{blob.traits.vision.toFixed(2)}</small>
          </dd>
        </div>
        <div>
          <dt>Anim left</dt>
          <dd>{blob.actionTimer > 0 ? `${blob.actionTimer.toFixed(2)}s` : '—'}</dd>
        </div>
        <div>
          <dt>Family</dt>
          <dd>
            gen {blob.generation} · parent {blob.parentId || 'seed'} · kids {blob.children}
          </dd>
        </div>
        <div>
          <dt>Meals</dt>
          <dd>{blob.meals}</dd>
        </div>
      </dl>
    </aside>
  )
}

args.streamContent:
:root {
  color-scheme: dark;
  --bg: #121820;
  --panel: #1a232c;
  --ink: #e6eee8;
  --muted: #9aaca2;
  --line: #2a3840;
  --fruit: #8ee05c;
  --blue: #3ec4e8;
  --red: #f05662;
  --gold: #e0c078;
  --celadon: #8fb8a0;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  min-height: 100%;
  background: var(--bg);
  color: var(--ink);
  font-family: Figtree, system-ui, sans-serif;
}

body {
  background:
    radial-gradient(900px 420px at 32% 18%, rgba(120, 160, 140, 0.14), transparent 60%),
    radial-gradient(700px 380px at 80% 0%, rgba(40, 70, 110, 0.22), transparent 55%),
    var(--bg);
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

h1,
h2 {
  text-wrap: balance;
}

.app {
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 0;
}

.mast {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 22px 8px;
}

.mast h1 {
  margin: 0;
  font-family: 'Bricolage Grotesque', Figtree, sans-serif;
  font-size: clamp(1.4rem, 2.4vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--ink);
}

.live {
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  font-size: 0.92rem;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
  margin-right: 4px;
}

.dot.fruit {
  background: var(--fruit);
}
.dot.blue {
  background: var(--blue);
}
.dot.red {
  background: var(--red);
}

.clock {
  margin-left: 8px;
  font-family: 'JetBrains Mono', monospace;
  color: var(--gold);
}

main {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(280px, 360px);
  gap: 12px;
  padding: 0 16px 8px;
  min-height: 0;
}

.stage {
  position: relative;
  min-height: 420px;
  border: 1px solid var(--line);
  background: #151c24;
  overflow: hidden;
}

.garden {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 420px;
}

.garden canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
}

.garden canvas:active {
  cursor: grabbing;
}

.garden-hint {
  position: absolute;
  left: 14px;
  bottom: 10px;
  margin: 0;
  color: var(--muted);
  font-size: 0.78rem;
  pointer-events: none;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
  max-height: calc(100vh - 220px);
  overflow: auto;
  padding: 10px 12px 16px;
  border: 1px solid var(--line);
  background: var(--panel);
}

.transport,
.presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.transport button,
.presets button,
.speed select {
  background: #12181f;
  border: 1px solid var(--line);
  padding: 6px 10px;
  border-radius: 8px;
}

.transport button.on,
.presets button.on {
  background: #24342c;
  border-color: var(--celadon);
  color: #d7efe0;
}

.speed {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted);
  font-size: 0.85rem;
}

.knobs section {
  margin-top: 12px;
}

.knobs header h2 {
  margin: 0;
  font-size: 0.92rem;
  font-weight: 650;
}

.knobs header p {
  margin: 2px 0 8px;
  color: var(--muted);
  font-size: 0.78rem;
}

.knob {
  display: grid;
  gap: 2px;
  margin-bottom: 8px;
}

.knob-top {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 0.8rem;
}

.knob-top em {
  font-style: normal;
  color: var(--gold);
  font-size: 0.68rem;
  margin-left: 6px;
}

.knob-val {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.75rem;
  color: var(--celadon);
}

.knob input[type='range'] {
  width: 100%;
  accent-color: var(--celadon);
}

.inspector {
  position: absolute;
  right: 12px;
  top: 12px;
  width: min(260px, 70%);
  padding: 10px 12px;
  background: #1b252e;
  border: 1px solid var(--line);
  border-radius: 12px;
  font-size: 0.82rem;
}

.inspector.empty {
  color: var(--muted);
}

.inspector.empty p {
  margin: 0;
}

.inspector header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
}

.inspector[data-kind='blue'] header b {
  color: var(--blue);
}
.inspector[data-kind='red'] header b {
  color: var(--red);
}

.inspector dl {
  margin: 0;
  display: grid;
  gap: 6px;
}

.inspector dl div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.inspector dt {
  color: var(--muted);
}
.inspector dd {
  margin: 0;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.inspector small {
  color: var(--muted);
}

.charts {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(160px, 220px) minmax(160px, 220px) minmax(220px, 1fr);
  gap: 10px;
  padding: 8px 16px 16px;
}

.chart-main,
.chart-side,
.summary {
  border: 1px solid var(--line);
  background: var(--panel);
  padding: 8px 10px 10px;
  min-height: 150px;
  display: flex;
  flex-direction: column;
}

.chart-main header,
.charts h2 {
  margin: 0 0 6px;
  font-size: 0.8rem;
  font-weight: 650;
}

.chart-main header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}

.legend {
  display: flex;
  gap: 10px;
  list-style: none;
  margin: 0;
  padding: 0;
  font-size: 0.75rem;
  color: var(--muted);
}

.legend i {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 4px;
}

.plot {
  width: 100%;
  flex: 1;
  min-height: 110px;
}

.plot.mini {
  min-height: 54px;
}

.traits {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.78rem;
  color: var(--muted);
}

.traits p {
  margin: 0;
}

.traits b {
  color: var(--ink);
  font-family: 'JetBrains Mono', monospace;
  font-weight: 500;
}

.summary .headline {
  margin: 0 0 8px;
  font-size: 0.95rem;
  font-weight: 650;
}

.summary ul {
  margin: 0;
  padding-left: 16px;
  color: var(--muted);
  font-size: 0.8rem;
}

.summary .meta {
  margin: 10px 0 0;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.68rem;
  color: var(--muted);
}

.summary[data-tone='wave'] .headline,
.summary[data-tone='balanced'] .headline {
  color: var(--celadon);
}
.summary[data-tone='small'] .headline {
  color: var(--gold);
}
.summary[data-tone='faded'] .headline {
  color: var(--red);
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

@media (max-width: 1100px) {
  main {
    grid-template-columns: 1fr;
  }
  .controls {
    max-height: none;
  }
  .charts {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 720px) {
  .charts {
    grid-template-columns: 1fr;
