  font-size: 0.8rem;
  font-weight: 650;
}

.chart-main header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}

.legend {
  display: flex;
  gap: 10px;
  list-style: none;
  margin: 0;
  padding: 0;
  font-size: 0.75rem;
  color: var(--muted);
}

.legend i {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 4px;
}

.plot {
  width: 100%;
  flex: 1;
  min-height: 110px;
}

.plot.mini {
  min-height: 54px;
}

.traits {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.78rem;
  color: var(--muted);
}

.traits p {
  margin: 0;
}

.traits b {
  color: var(--ink);
  font-family: 'JetBrains Mono', monospace;
  font-weight: 500;
}

.summary .headline {
  margin: 0 0 8px;
  font-size: 0.95rem;
  font-weight: 650;
}

.summary ul {
  margin: 0;
  padding-left: 16px;
  color: var(--muted);
  font-size: 0.8rem;
}

.summary .meta {
  margin: 10px 0 0;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.68rem;
  color: var(--muted);
}

.summary[data-tone='wave'] .headline,
.summary[data-tone='balanced'] .headline {
  color: var(--celadon);
}
.summary[data-tone='small'] .headline {
  color: var(--gold);
}
.summary[data-tone='faded'] .headline {
  color: var(--red);
}

