for (const t of [120, 200, 350, 500]) {
  const e = new Engine(DEFAULT_PARAMS)
  e.run(t)
  const reds = e.world.blobs.filter(b=>b.kind==="red")
  const meanR = reds.length ? reds.reduce((s,b)=>s+b.energy,0)/reds.length : 0
  console.log(t, {blue:e.world.counts.blue, red:e.world.counts.red, fruit:e.world.counts.fruit, contacts:e.world.totals.contacts, rb:e.world.totals.births.red, rd:e.world.totals.deaths.red, meanR:meanR.toFixed(1)})
}
'

